const std = @import("std");
const math = std.math;
const mem = std.mem;
const testing = std.testing;
const Allocator = mem.Allocator;

pub const Shape = []const usize;

pub fn totalElements(shape: Shape) usize {
    var total: usize = 1;
    for (shape) |dim| {
        total *= dim;
    }
    return total;
}

pub const Tensor = struct {
    allocator: Allocator,
    data: []f64,
    shape: Shape,
    strides: []usize,
    offset: usize = 0,
    is_view: bool = false,
    requires_grad: bool = false,
    grad: ?Tensor = null,

    pub fn init(allocator: Allocator, shape: Shape) !Tensor {
        const total = totalElements(shape);
        const data = try allocator.alloc(f64, total);
        errdefer allocator.free(data);
        mem.set(f64, data, 0.0);
        const shape_copy = try allocator.dupe(usize, shape);
        errdefer allocator.free(shape_copy);
        const strides_len = shape.len;
        var strides = try allocator.alloc(usize, strides_len);
        errdefer allocator.free(strides);
        if (strides_len > 0) {
            strides[strides_len - 1] = 1;
            var i: usize = strides_len;
            while (i > 1) : (i -= 1) {
                strides[i - 1] = strides[i] * shape[i];
            }
        }
        return Tensor{
            .allocator = allocator,
            .data = data,
            .shape = shape_copy,
            .strides = strides,
            .is_view = false,
        };
    }

    pub fn deinit(self: *Tensor) void {
        if (!self.is_view) {
            self.allocator.free(self.data);
        }
        self.allocator.free(self.shape);
        self.allocator.free(self.strides);
        if (self.grad) |*g| {
            g.deinit();
            self.grad = null;
        }
    }

    pub fn view(self: Tensor, allocator: Allocator, new_shape: Shape) !Tensor {
        if (totalElements(self.shape) != totalElements(new_shape)) {
            return error.ShapeMismatch;
        }
        const shape_copy = try allocator.dupe(usize, new_shape);
        errdefer allocator.free(shape_copy);
        const strides_len = new_shape.len;
        var strides = try allocator.alloc(usize, strides_len);
        errdefer allocator.free(strides);
        if (strides_len > 0) {
            strides[strides_len - 1] = 1;
            var i: usize = strides_len;
            while (i > 1) : (i -= 1) {
                strides[i - 1] = strides[i] * new_shape[i];
            }
        }
        return Tensor{
            .allocator = allocator,
            .data = self.data,
            .shape = shape_copy,
            .strides = strides,
            .offset = self.offset,
            .is_view = true,
            .requires_grad = self.requires_grad,
            .grad = if (self.grad) |g| g else null,
        };
    }

    pub fn reshape(self: *Tensor, allocator: Allocator, new_shape: Shape) !Tensor {
        return try self.view(allocator, new_shape);
    }

    pub fn get(self: *const Tensor, indices: []const usize) f64 {
        if (indices.len != self.shape.len) {
            @panic("Dimension mismatch in get");
        }
        var idx: usize = self.offset;
        for (indices, 0..) |i, dim| {
            if (i >= self.shape[dim]) {
                @panic("Index out of bounds");
            }
            idx += i * self.strides[dim];
        }
        return self.data[idx];
    }

    pub fn set(self: *Tensor, indices: []const usize, value: f64) void {
        if (indices.len != self.shape.len) {
            @panic("Dimension mismatch in set");
        }
        var idx: usize = self.offset;
        for (indices, 0..) |i, dim| {
            if (i >= self.shape[dim]) {
                @panic("Index out of bounds");
            }
            idx += i * self.strides[dim];
        }
        self.data[idx] = value;
    }

    pub fn add(self: *const Tensor, other: *const Tensor, result: *Tensor) !void {
        if (self.shape.len != other.shape.len or self.shape.len != result.shape.len or !mem.eql(usize, self.shape, other.shape)) {
            return error.ShapeMismatch;
        }
        const total = totalElements(self.shape);
        for (0..total) |i| {
            const self_idx = self.offset + i;
            const other_idx = other.offset + i;
            const result_idx = result.offset + i;
            result.data[result_idx] = self.data[self_idx] + other.data[other_idx];
        }
    }

    pub fn mul(self: *const Tensor, other: *const Tensor, result: *Tensor) !void {
        if (self.shape.len != other.shape.len or self.shape.len != result.shape.len or !mem.eql(usize, self.shape, other.shape)) {
            return error.ShapeMismatch;
        }
        const total = totalElements(self.shape);
        for (0..total) |i| {
            const self_idx = self.offset + i;
            const other_idx = other.offset + i;
            const result_idx = result.offset + i;
            result.data[result_idx] = self.data[self_idx] * other.data[other_idx];
        }
    }

    pub fn matmul(self: *const Tensor, other: *const Tensor, result: *Tensor) !void {
        if (self.shape.len != 2 or other.shape.len != 2 or self.shape[1] != other.shape[0] or result.shape.len != 2 or result.shape[0] != self.shape[0] or result.shape[1] != other.shape[1]) {
            return error.ShapeMismatch;
        }
        const m = self.shape[0];
        const n = other.shape[1];
        const k = self.shape[1];
        const self_offset = self.offset;
        const other_offset = other.offset;
        const result_offset = result.offset;
        mem.set(f64, result.data[result_offset..], 0.0);
        const self_data = self.data[self_offset..];
        const other_data = other.data[other_offset..];
        const result_data = result.data[result_offset..];
        for (0..m) |i| {
            for (0..n) |j| {
                var sum: f64 = 0.0;
                for (0..k) |l| {
                    sum += self_data[i * k + l] * other_data[l * n + j];
                }
                result_data[i * n + j] = sum;
            }
        }
    }

    pub fn transpose(self: *const Tensor, allocator: Allocator) !Tensor {
        if (self.shape.len != 2) {
            return error.ShapeMismatch;
        }
        const m = self.shape[0];
        const n = self.shape[1];
        var result = try Tensor.init(allocator, &.{ n, m });
        const self_offset = self.offset;
        const result_offset = result.offset;
        const self_data = self.data[self_offset..];
        const result_data = result.data[result_offset..];
        mem.set(f64, result.data[result_offset..], 0.0);
        for (0..m) |i| {
            for (0..n) |j| {
                result_data[j * m + i] = self_data[i * n + j];
            }
        }
        return result;
    }

    pub fn sum(self: *const Tensor, allocator: Allocator) !Tensor {
        const total = totalElements(self.shape);
        var s: f64 = 0.0;
        for (0..total) |i| {
            s += self.data[self.offset + i];
        }
        var result = try Tensor.init(allocator, &.{1});
        result.data[0] = s;
        return result;
    }

    pub fn mean(self: *const Tensor, allocator: Allocator) !Tensor {
        const sum_tensor = try self.sum(allocator);
        defer sum_tensor.deinit();
        const total = @as(f64, @floatFromInt(totalElements(self.shape)));
        var result = try Tensor.init(allocator, &.{1});
        result.data[0] = sum_tensor.data[0] / total;
        return result;
    }

    test "tensor init and basic ops" {
        var gpa = std.heap.GeneralPurposeAllocator(.{}){};
        defer _ = gpa.deinit();
        const allocator = gpa.allocator();
        const shape = &[_]usize{ 2, 3 };
        var tensor = try Tensor.init(allocator, shape);
        defer tensor.deinit();
        try tensor.set(&.{ 0, 0 }, 1.0);
        try tensor.set(&.{ 1, 2 }, 6.0);
        try testing.expectEqual(1.0, tensor.get(&.{ 0, 0 }));
    }

    test "matmul" {
        var gpa = std.heap.GeneralPurposeAllocator(.{}){};
        defer _ = gpa.deinit();
        const allocator = gpa.allocator();
        const shape_a = &[_]usize{ 2, 3 };
        const shape_b = &[_]usize{ 3, 4 };
        const shape_c = &[_]usize{ 2, 4 };
        var a = try Tensor.init(allocator, shape_a);
        defer a.deinit();
        var b = try Tensor.init(allocator, shape_b);
        defer b.deinit();
        var c = try Tensor.init(allocator, shape_c);
        defer c.deinit();
        try a.set(&.{ 0, 0 }, 1.0);
        try a.set(&.{ 0, 1 }, 2.0);
        try a.set(&.{ 0, 2 }, 3.0);
        try a.set(&.{ 1, 0 }, 4.0);
        try a.set(&.{ 1, 1 }, 5.0);
        try a.set(&.{ 1, 2 }, 6.0);
        try b.set(&.{ 0, 0 }, 7.0);
        try b.set(&.{ 0, 1 }, 8.0);
        try b.set(&.{ 0, 2 }, 9.0);
        try b.set(&.{ 0, 3 }, 10.0);
        try b.set(&.{ 1, 0 }, 11.0);
        try b.set(&.{ 1, 1 }, 12.0);
        try b.set(&.{ 1, 2 }, 13.0);
        try b.set(&.{ 1, 3 }, 14.0);
        try b.set(&.{ 2, 0 }, 15.0);
        try b.set(&.{ 2, 1 }, 16.0);
        try b.set(&.{ 2, 2 }, 17.0);
        try b.set(&.{ 2, 3 }, 18.0);
        try a.matmul(&b, &c);
        try testing.expectEqual(140.0, c.get(&.{ 0, 0 }));
        try testing.expectEqual(152.0, c.get(&.{ 0, 1 }));
    }

    pub fn clone(self: *const Tensor, allocator: Allocator) !Tensor {
        var cloned = try Tensor.init(allocator, self.shape);
        @memcpy(cloned.data.ptr, self.data.ptr, self.data.len * @sizeOf(f64));
        return cloned;
    }

    pub fn zeroGrad(self: *Tensor) void {
        if (self.grad) |*g| {
            mem.set(f64, g.data, 0.0);
        }
    }

    pub fn backward(self: *Tensor, grad_output: *const Tensor) void {
        if (!self.requires_grad) return;
        if (self.grad == null) {
            self.grad = Tensor.init(self.allocator, self.shape) catch return;
        }
        self.grad.?.add(grad_output, &self.grad.?, {}) catch return;
    }
};
